if ($CapturarLog) { $TestarFluidez = $true }
if (($TestarApresentacao -or $TestarSeries -or $TestarLista -or $TestarFluidez -or $TestarFluidez -or $TestarFluidez -or $TestarFluidez -or $TestarFluidez -or $TestarFluidez) -and $NaoCompilar) { throw 'Testes nativos exigem compilacao. Nada foi alterado.' }
